"""Offline landmark extraction pipeline for the trampoline demo."""

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import cv2
import mediapipe as mp

from trampoline.bed_calibration import load_calibration
from trampoline.schema import (
    AnalysisArtifactRef,
    JumpSegment,
    ManualOverride,
    OverridesArtifact,
    RoutineAnalysis,
)


PROJECT_ROOT = Path(__file__).resolve().parent.parent
LANDMARKS_FILENAME = "landmarks.jsonl"
FRAMES_META_FILENAME = "frames_meta.json"
ANALYSIS_FILENAME = "analysis.json"
SEGMENTATION_FILENAME = "segmentation.json"
OVERRIDES_FILENAME = "overrides.json"
LANDMARK_NAMES = [landmark.name.lower() for landmark in mp.solutions.pose.PoseLandmark]
POSE_CONNECTIONS = sorted(
    (int(start), int(end)) for start, end in mp.solutions.pose.POSE_CONNECTIONS
)


def initialize_analysis(analysis_id: str, source_video: str) -> RoutineAnalysis:
    """Create the baseline analysis object used by the Phase 1 pipeline."""

    return RoutineAnalysis(analysis_id=analysis_id, source_video=source_video)


def resolve_analysis_dir(output_root: Path, analysis_id: str) -> Path:
    """Return the canonical output directory path for an analysis run."""

    return output_root / analysis_id


def repo_relative_path(path: Path) -> str:
    """Prefer repository-relative artifact paths so reports stay portable."""

    resolved = path.resolve()
    try:
        return str(resolved.relative_to(PROJECT_ROOT))
    except ValueError:
        return str(resolved)


def resolve_repo_path(path_str: str) -> Path:
    """Resolve either repo-relative or absolute paths back to a filesystem path."""

    path = Path(path_str)
    return path if path.is_absolute() else PROJECT_ROOT / path


def timestamp_ms_for_frame(frame_index: int, fps: float) -> int:
    """Map one frame index to a millisecond timestamp."""

    safe_fps = fps if fps > 0 else 30.0
    return int(round((frame_index * 1000.0) / safe_fps))


def build_frames_meta(
    *,
    source_video: str,
    fps: float,
    frame_count: int,
    width: int,
    height: int,
) -> dict[str, Any]:
    """Build the JSON payload that maps each frame index to its timestamp."""

    frames = [
        {
            "frame_index": frame_index,
            "timestamp_ms": timestamp_ms_for_frame(frame_index, fps),
        }
        for frame_index in range(frame_count)
    ]
    duration_ms = frames[-1]["timestamp_ms"] if frames else 0
    return {
        "source_video": source_video,
        "fps": fps,
        "frame_count": frame_count,
        "width": width,
        "height": height,
        "duration_ms": duration_ms,
        "frames": frames,
        "generated_at": datetime.now(timezone.utc).isoformat(),
    }


def serialize_landmarks(landmarks: Any) -> list[dict[str, float | int | str | None]]:
    """Convert MediaPipe landmarks into a stable JSON-serializable format."""

    if not landmarks:
        return []

    rows: list[dict[str, float | int | str | None]] = []
    for index, landmark in enumerate(landmarks):
        rows.append(
            {
                "index": index,
                "name": LANDMARK_NAMES[index],
                "x": float(landmark.x),
                "y": float(landmark.y),
                "z": float(landmark.z),
                "visibility": float(getattr(landmark, "visibility", 0.0)),
                "presence": float(getattr(landmark, "presence", 0.0))
                if hasattr(landmark, "presence")
                else None,
            }
        )
    return rows


def write_json(path: Path, payload: Any) -> None:
    """Write one JSON payload using stable formatting."""

    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")


def read_json(path: Path) -> Any:
    """Read one JSON file from disk."""

    return json.loads(path.read_text(encoding="utf-8"))


def upsert_artifact(
    artifacts: list[AnalysisArtifactRef],
    *,
    name: str,
    path: Path,
    media_type: str,
    description: str,
) -> list[AnalysisArtifactRef]:
    """Insert or replace one artifact entry while preserving order for others."""

    artifact = AnalysisArtifactRef(
        name=name,
        path=repo_relative_path(path),
        media_type=media_type,
        description=description,
    )
    updated = [item for item in artifacts if item.name != name]
    updated.append(artifact)
    return updated


def load_analysis_model(analysis_dir: Path) -> RoutineAnalysis:
    """Load the persisted analysis contract from disk."""

    analysis_path = analysis_dir / ANALYSIS_FILENAME
    if analysis_path.is_file():
        return RoutineAnalysis.model_validate_json(analysis_path.read_text(encoding="utf-8"))

    frames_meta = read_json(analysis_dir / FRAMES_META_FILENAME)
    return initialize_analysis(
        analysis_id=analysis_dir.name,
        source_video=frames_meta["source_video"],
    )


def save_analysis_model(analysis_dir: Path, analysis: RoutineAnalysis) -> Path:
    """Persist the canonical analysis contract to disk."""

    analysis_dir.mkdir(parents=True, exist_ok=True)
    analysis_path = analysis_dir / ANALYSIS_FILENAME
    write_json(analysis_path, analysis.model_dump(mode="json"))
    return analysis_path


def load_segmentation_payload(analysis_dir: Path) -> dict[str, Any] | None:
    """Load the automatic segmentation artifact when present."""

    path = analysis_dir / SEGMENTATION_FILENAME
    if not path.is_file():
        return None
    return read_json(path)


def load_overrides_artifact(analysis_dir: Path) -> OverridesArtifact | None:
    """Load the persisted timeline overrides when present."""

    path = analysis_dir / OVERRIDES_FILENAME
    if not path.is_file():
        return None
    return OverridesArtifact.model_validate_json(path.read_text(encoding="utf-8"))


def save_overrides_artifact(analysis_dir: Path, overrides: OverridesArtifact) -> Path:
    """Persist one overrides artifact."""

    analysis_dir.mkdir(parents=True, exist_ok=True)
    path = analysis_dir / OVERRIDES_FILENAME
    write_json(path, overrides.model_dump(mode="json"))
    return path


def normalize_jump_segments(jump_segments: list[JumpSegment]) -> list[JumpSegment]:
    """Sort and re-index jump segments while preserving their ids."""

    normalized: list[JumpSegment] = []
    for index, segment in enumerate(sorted(jump_segments, key=lambda item: (item.start_ms, item.end_ms, item.jump_id))):
        normalized.append(segment.model_copy(update={"sequence_index": index}))
    return normalized


def derive_manual_overrides(
    auto_segments: list[JumpSegment],
    merged_segments: list[JumpSegment],
) -> list[ManualOverride]:
    """Summarize persisted jump edits into stable override metadata."""

    overrides: list[ManualOverride] = []
    auto_by_id = {segment.jump_id: segment for segment in auto_segments}

    if len(merged_segments) != len(auto_segments):
        overrides.append(
            ManualOverride(
                operation="replace_segments",
                jump_ids=[segment.jump_id for segment in merged_segments],
                reason="timeline topology changed via split/merge",
            )
        )

    for segment in merged_segments:
        lineage = segment.auto_jump_ids or [segment.jump_id]
        if len(lineage) > 1:
            overrides.append(
                ManualOverride(
                    operation="merge_jumps",
                    jump_ids=lineage,
                    result_jump_id=segment.jump_id,
                    reason="merged adjacent jump segments",
                )
            )
        elif lineage[0] in auto_by_id:
            auto_segment = auto_by_id[lineage[0]]
            for field_name in ("start_ms", "takeoff_ms", "apex_ms", "landing_ms", "end_ms"):
                merged_value = getattr(segment, field_name)
                if merged_value != getattr(auto_segment, field_name):
                    overrides.append(
                        ManualOverride(
                            operation="update_boundary",
                            jump_id=segment.jump_id,
                            field_name=field_name,
                            value_ms=merged_value,
                            reason="manual boundary adjustment",
                        )
                    )

"""Shared schema objects for trampoline analysis artifacts."""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Literal, Optional

from pydantic import BaseModel, Field, field_validator, model_validator


ArtifactMediaType = Literal["json", "jsonl", "video", "image", "text", "directory"]
JumpSource = Literal["auto", "manual", "merged"]
OverrideFieldName = Literal["start_ms", "takeoff_ms", "apex_ms", "landing_ms", "end_ms"]
OverrideOperation = Literal["update_boundary", "split_jump", "merge_jumps", "replace_segments"]
RoutineStatus = Literal["pending", "running", "complete", "needs_review", "failed"]


class AnalysisArtifactRef(BaseModel):
    """Reference to a generated artifact inside an analysis directory."""

    name: str = Field(..., min_length=1)
    path: str = Field(..., min_length=1)
    media_type: ArtifactMediaType = "json"
    description: Optional[str] = None


class ManualOverride(BaseModel):
    """Human-authored jump timeline edit metadata."""

    jump_id: Optional[str] = Field(default=None, min_length=1)
    jump_ids: list[str] = Field(default_factory=list)
    operation: OverrideOperation = "update_boundary"
    field_name: Optional[OverrideFieldName] = None
    value_ms: Optional[int] = Field(default=None, ge=0)
    result_jump_id: Optional[str] = Field(default=None, min_length=1)
    reason: Optional[str] = None
    author: str = Field(default="operator", min_length=1)
    applied: bool = True

    @field_validator("jump_ids")
    @classmethod
    def validate_jump_ids(cls, jump_ids: list[str]) -> list[str]:
        if any(not jump_id.strip() for jump_id in jump_ids):
            raise ValueError("jump_ids cannot contain blank strings")
        return jump_ids

    @model_validator(mode="after")
    def validate_override_shape(self) -> "ManualOverride":
        if self.operation == "update_boundary":
            if not self.jump_id or self.field_name is None or self.value_ms is None:
                raise ValueError("update_boundary overrides require jump_id, field_name, and value_ms")
            return self

        if self.operation == "split_jump":
            if not self.jump_id or self.value_ms is None:
                raise ValueError("split_jump overrides require jump_id and value_ms")
            return self

        if self.operation in {"merge_jumps", "replace_segments"} and not self.jump_ids:
            raise ValueError(f"{self.operation} overrides require jump_ids")
        return self


class JumpSegment(BaseModel):
    """Canonical representation of one jump boundary set."""

    jump_id: str = Field(..., min_length=1)
    sequence_index: int = Field(..., ge=0)
    start_ms: int = Field(..., ge=0)
    takeoff_ms: int = Field(..., ge=0)
    apex_ms: int = Field(..., ge=0)
    landing_ms: int = Field(..., ge=0)
    end_ms: int = Field(..., ge=0)
    label: Optional[str] = None
    source: JumpSource = "auto"
    confidence: Optional[float] = Field(default=None, ge=0.0, le=1.0)
    notes: list[str] = Field(default_factory=list)
    auto_jump_ids: list[str] = Field(default_factory=list)
    manual_boundary_fields: list[OverrideFieldName] = Field(default_factory=list)

    @field_validator("notes")
    @classmethod
    def validate_notes(cls, notes: list[str]) -> list[str]:
        if any(not note.strip() for note in notes):
            raise ValueError("notes cannot contain blank strings")
        return notes

    @field_validator("auto_jump_ids")
    @classmethod
    def validate_auto_jump_ids(cls, auto_jump_ids: list[str]) -> list[str]:
        if any(not jump_id.strip() for jump_id in auto_jump_ids):
            raise ValueError("auto_jump_ids cannot contain blank strings")
        deduped = list(dict.fromkeys(auto_jump_ids))
        return deduped

    @field_validator("manual_boundary_fields")
    @classmethod
    def validate_manual_fields(cls, fields: list[OverrideFieldName]) -> list[OverrideFieldName]:
        return list(dict.fromkeys(fields))

    @model_validator(mode="after")
    def validate_time_order(self) -> "JumpSegment":
        ordered_times = [
            self.start_ms,
            self.takeoff_ms,
            self.apex_ms,
            self.landing_ms,
            self.end_ms,
        ]
        if ordered_times != sorted(ordered_times):
            raise ValueError("jump timing fields must be monotonically increasing")
        if not self.auto_jump_ids:
            self.auto_jump_ids = [self.jump_id]
        return self


class OverridesArtifact(BaseModel):
    """Persisted manual timeline edits for one analysis."""

    analysis_id: str = Field(..., min_length=1)
    jump_segments: list[JumpSegment] = Field(default_factory=list)
    manual_overrides: list[ManualOverride] = Field(default_factory=list)
    updated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))


class RoutineAnalysis(BaseModel):
    """Top-level analysis contract shared by CLI, pipeline, and app layers."""

    analysis_id: str = Field(..., min_length=1)
    source_video: str = Field(..., min_length=1)
    discipline: Literal["TRA"] = "TRA"
    athlete_count: Literal[1] = 1
    routine_label: str = Field(default="single_person_tra_demo", min_length=1)
    status: RoutineStatus = "pending"
    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    jump_segments: list[JumpSegment] = Field(default_factory=list)
    manual_overrides: list[ManualOverride] = Field(default_factory=list)
    artifacts: list[AnalysisArtifactRef] = Field(default_factory=list)

        }

        const duration = Math.max(totalDurationMs(), segments[segments.length - 1].end_ms);
        timelineSummary.textContent = `${segments.length} jumps loaded${state.dirty ? " • unsaved edits" : ""}. Click a block to seek and edit.`;
        detailTimeline.textContent = `${segments.length} jumps`;

        segments.forEach((segment) => {
            const button = document.createElement("button");
            const left = (segment.start_ms / duration) * 100;
            const width = Math.max(((segment.end_ms - segment.start_ms) / duration) * 100, 4);
            const currentMs = currentVideoMs();
            const isCurrent = currentMs >= segment.start_ms && currentMs <= segment.end_ms;
            const isSelected = segment.jump_id === state.selected_jump_id;
            button.type = "button";
            button.className = `timeline-block${isSelected ? " selected" : ""}${isCurrent ? " current" : ""}`;
            button.dataset.jumpId = segment.jump_id;
            button.style.left = `${left}%`;
            button.style.width = `${width}%`;
            button.innerHTML = `
                <span class="timeline-block-id">${segment.sequence_index + 1}</span>
                <span class="timeline-block-time">${segment.start_ms}-${segment.end_ms}ms</span>
            `;
            button.addEventListener("click", () => {
                state.selected_jump_id = segment.jump_id;
                previewVideo.currentTime = segment.start_ms / 1000;
                renderTimeline();
                syncBoundaryInputs();
            });
            timelineTrack.appendChild(button);
        });
        syncBoundaryInputs();
    }

    function renderResult() {
        const result = state.selected_result;
        const analysisId = currentAnalysisId();
        detailAnalysisId.textContent = analysisId || "none";

        if (!result) {
            previewVideo.removeAttribute("src");
            detailVideoMeta.textContent = "waiting";
            detailCalibration.textContent = "not saved";
            detailTimeline.textContent = "no jumps";
            detailSummary.textContent = "Select an analysis to view its video preview, skeleton overlay, calibration, and current jump selection.";
            fillCalibrationInputs(null);
            syncSegmentsFromResult(null);
            drawOverlay();
            renderTimeline();
            return;
        }

        previewVideo.src = `/api/trampoline/video/${result.analysis_id}`;
        detailVideoMeta.textContent = `${result.frames_meta.width}x${result.frames_meta.height} @ ${result.frames_meta.fps.toFixed(2)}fps`;
        detailCalibration.textContent = result.calibration ? "saved" : "not saved";
        detailSummary.textContent = `Frame ${result.preview_frame.frame_index} at ${result.preview_frame.timestamp_ms}ms with ${result.preview_frame.landmarks.length} landmarks.`;
        fillCalibrationInputs(result.calibration);
        syncSegmentsFromResult(result);
        drawOverlay();
        renderTimeline();
    }

    function renderAnalysisList() {
        analysisList.innerHTML = "";
        for (const item of state.analyses || []) {
            const button = document.createElement("button");
            button.type = "button";
            button.className = item.analysis_id === currentAnalysisId() ? "active" : "";
            button.innerHTML = `
                <span>${item.analysis_id}</span>
                <span>${item.has_segmentation ? "seg" : "raw"} · ${item.frame_count}f</span>
            `;
            button.addEventListener("click", () => {
                fetch(`/api/trampoline/result/${item.analysis_id}`)
                    .then((response) => response.json())
                    .then((payload) => {
                        if (!payload.success) {
                            throw new Error(payload.error || "Failed to load analysis");
                        }
                        setCurrentAnalysisId(item.analysis_id);
                        state.selected_result = payload.result;
                        renderAnalysisList();
                        renderResult();
                        setStatus(payload.status);
                        window.history.replaceState({}, "", `/trampoline?analysis_id=${item.analysis_id}`);
                    })
                    .catch((error) => {
                        setStatus(error.message);
                    });
            });
            analysisList.appendChild(button);
        }
    }

    function pollStatus(analysisId) {
        const poll = () => {
            fetch(`/api/trampoline/status/${analysisId}`)
                .then((response) => response.json())
                .then((payload) => {
                    if (!payload.success) {
                        throw new Error(payload.error || "status failed");
                    }
                    setStatus(payload.status);
                    if (payload.result) {
                        state.selected_result = payload.result;
                        setCurrentAnalysisId(analysisId);
                        state.analyses = state.analyses || [];
                        if (!state.analyses.find((item) => item.analysis_id === analysisId)) {
                            state.analyses.push({
                                analysis_id: analysisId,
                                frame_count: payload.result.frames_meta.frame_count,
                                duration_ms: payload.result.frames_meta.duration_ms,
                                source_video: payload.result.source_video,
                                updated_at: payload.result.updated_at,
                                has_segmentation: Boolean(payload.result.segmentation),
                                has_overrides: Boolean(payload.result.has_overrides),
                            });
                        }
                        renderAnalysisList();
                        renderResult();
                    }
                    if (payload.status === "queued" || payload.status === "running") {
                        window.setTimeout(poll, 800);
                    }
                })
                .catch((error) => {
                    setStatus(error.message);
                });
        };
        poll();
    }

    function reframeSegment(original, newStart, newEnd, jumpId) {
        const baseDuration = Math.max(original.end_ms - original.start_ms, 1);
        const newDuration = Math.max(newEnd - newStart, 1);
        const ratios = {
            takeoff_ms: (original.takeoff_ms - original.start_ms) / baseDuration,
            apex_ms: (original.apex_ms - original.start_ms) / baseDuration,
            landing_ms: (original.landing_ms - original.start_ms) / baseDuration,
        };
        return normalizeSegment({
            ...clone(original),
            jump_id: jumpId,
            start_ms: Math.round(newStart),
            takeoff_ms: Math.round(newStart + (newDuration * ratios.takeoff_ms)),
            apex_ms: Math.round(newStart + (newDuration * ratios.apex_ms)),
            landing_ms: Math.round(newStart + (newDuration * ratios.landing_ms)),
            end_ms: Math.round(newEnd),
            source: "merged",
        });
    }

    function refreshSequenceIds() {
        state.editable_segments = state.editable_segments
            .slice()
            .sort((left, right) => left.start_ms - right.start_ms)
            .map((segment, index) => ({
                ...segment,
                jump_id: `jump-${String(index + 1).padStart(3, "0")}`,
                sequence_index: index,
            }));
        if (state.editable_segments.length && !state.editable_segments.find((segment) => segment.jump_id === state.selected_jump_id)) {
            state.selected_jump_id = state.editable_segments[0].jump_id;
        }
    }

    uploadForm.addEventListener("submit", (event) => {
        event.preventDefault();
        const file = videoInput.files[0];
        if (!file) {
            setStatus("choose a video");
            return;
        }

        const formData = new FormData();
        formData.append("video", file);
        setStatus("uploading");
        fetch("/api/trampoline/upload", {
            method: "POST",
            body: formData,
        })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "upload failed");
                }
                setCurrentAnalysisId(payload.analysis_id);
                state.selected_result = null;
                setStatus(payload.status);
                renderResult();
            })
            .catch((error) => {
                setStatus(error.message);
            });
    });

    analyzeButton.addEventListener("click", () => {
        const analysisId = currentAnalysisId();
        if (!analysisId) {
            return;
        }
        setStatus("queued");
        fetch("/api/trampoline/analyze", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ analysis_id: analysisId }),
        })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "analyze failed");
                }
                pollStatus(analysisId);
            })
            .catch((error) => {
                setStatus(error.message);
            });
    });

    segmentButton.addEventListener("click", () => {
        const analysisId = currentAnalysisId();
        if (!analysisId) {
            return;
        }
        setStatus("segmenting");
        fetch(`/api/trampoline/segment/${analysisId}`, {
            method: "POST",
        })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "segment failed");
                }
                state.selected_result = payload.result;
                renderAnalysisList();
                renderResult();
                setStatus("segmented");
            })
            .catch((error) => {
                setStatus(error.message);
            });
    });

    suggestCalibrationButton.addEventListener("click", () => {
        const corners = suggestedCalibration();
        if (!corners) {
            return;
        }
        fillCalibrationInputs({ corners });
    });

    document.getElementById("calibration-form").addEventListener("submit", (event) => {
        event.preventDefault();
        const analysisId = currentAnalysisId();
        if (!analysisId) {
            return;
        }
        fetch(`/api/trampoline/calibration/${analysisId}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ corners: getCalibrationCorners() }),
        })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "calibration save failed");
                }
                return fetch(`/api/trampoline/result/${analysisId}`);
            })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "result refresh failed");
                }
                state.selected_result = payload.result;
                renderAnalysisList();
                renderResult();
                setStatus("calibration saved");
            })
            .catch((error) => {
                setStatus(error.message);
            });
    });

    boundaryInputs.forEach((input) => {
        input.addEventListener("change", () => {
            const segment = selectedSegment();
            if (!segment) {
                return;
            }
            const index = selectedSegmentIndex();
            state.editable_segments[index] = normalizeSegment({
                ...segment,
                [input.dataset.boundary]: Number(input.value),
                source: "merged",
                manual_boundary_fields: boundaryFields(),
            });
            updateDirtyState(true);
            renderTimeline();
        });
    });

    splitJumpButton.addEventListener("click", () => {
        const segment = selectedSegment();
        if (!segment) {
            return;
        }
        const index = selectedSegmentIndex();
        const splitMs = Math.min(Math.max(currentVideoMs(), segment.start_ms + 80), segment.end_ms - 80);
        const left = reframeSegment(segment, segment.start_ms, splitMs, `${segment.jump_id}-a`);
        const right = reframeSegment(segment, splitMs, segment.end_ms, `${segment.jump_id}-b`);
        left.auto_jump_ids = clone(segment.auto_jump_ids || [segment.jump_id]);
        right.auto_jump_ids = clone(segment.auto_jump_ids || [segment.jump_id]);
        state.editable_segments.splice(index, 1, left, right);
        refreshSequenceIds();
        state.selected_jump_id = state.editable_segments[index].jump_id;
        updateDirtyState(true);
        renderTimeline();
    });

    mergeJumpButton.addEventListener("click", () => {
        const index = selectedSegmentIndex();
        const left = state.editable_segments[index];
        const right = state.editable_segments[index + 1];
        if (!left || !right) {
            return;
        }
        const merged = normalizeSegment({
            ...clone(left),
            start_ms: left.start_ms,
            takeoff_ms: Math.min(left.takeoff_ms, right.takeoff_ms),
            apex_ms: Math.round((left.apex_ms + right.apex_ms) / 2),
            landing_ms: Math.max(left.landing_ms, right.landing_ms),
            end_ms: right.end_ms,
            source: "merged",
            auto_jump_ids: Array.from(new Set([...(left.auto_jump_ids || [left.jump_id]), ...(right.auto_jump_ids || [right.jump_id])])),
            manual_boundary_fields: boundaryFields(),
        });
        state.editable_segments.splice(index, 2, merged);
        refreshSequenceIds();
        state.selected_jump_id = state.editable_segments[index].jump_id;
        updateDirtyState(true);
        renderTimeline();
    });

    resetJumpButton.addEventListener("click", () => {
        const index = selectedSegmentIndex();
        const segment = selectedSegment();
        if (!segment) {
            return;
        }
        const autoMatch = state.auto_segments.find((item) => (item.auto_jump_ids || [item.jump_id]).some((jumpId) => (segment.auto_jump_ids || []).includes(jumpId)));
        if (!autoMatch) {
            return;
        }
        state.editable_segments[index] = clone(autoMatch);
        updateDirtyState(true);
        renderTimeline();
    });

    saveOverridesButton.addEventListener("click", () => {
        const analysisId = currentAnalysisId();
        if (!analysisId) {
            return;
        }
        setStatus("saving");
        fetch(`/api/trampoline/overrides/${analysisId}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ jump_segments: state.editable_segments }),
        })
            .then((response) => response.json())
            .then((payload) => {
                if (!payload.success) {
                    throw new Error(payload.error || "override save failed");
                }
                state.selected_result = payload.result;
                renderAnalysisList();
                renderResult();
                setStatus("overrides saved");
            })
            .catch((error) => {
                setStatus(error.message);
            });
    });

    previewVideo.addEventListener("timeupdate", () => {
        if (state.editable_segments.length) {
            renderTimeline();
        }
    });

    setCurrentAnalysisId(state.selected_analysis_id || null);
    renderAnalysisList();
    renderResult();
    if (state.selected_analysis_id) {
        setStatus("done");
    }
})();

